BEGIN; INSERT INTO public.media_files(id,filename,original_name,path,mime_type,size,dataset,inserted_at,updated_at,workspace_id,project_id,dataset_id,object_key) SELECT md5('c102-fixture-'||n::text)::uuid,'fixture-'||n||'.bin','fixture-'||n||'.bin',CASE WHEN n IN(4,5) THEN 'fixture/shared.bin' ELSE 'fixture/row-'||n||'.bin' END,'application/octet-stream',10,m.dataset,m.inserted_at,m.updated_at,CASE WHEN n%2=0 THEN m.workspace_id ELSE NULL END,CASE WHEN n%2=0 THEN m.project_id ELSE NULL END,CASE WHEN n%2=0 THEN m.dataset_id ELSE NULL END,CASE WHEN n=1 THEN NULL WHEN n IN(2,3) THEN m.object_key ELSE 'fixture/key-'||n||'.bin' END FROM public.media_files m CROSS JOIN generate_series(1,10001) n WHERE m.id='6321ad64-e6ba-4ffa-989f-ed95f8a6f34d'::uuid; COMMIT;